using System.Collections.Concurrent;
using System.Diagnostics;
using System.IO;
using System.Runtime.InteropServices;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using Microsoft.Win32.SafeHandles;
using SmartFiles.Core;
namespace SmartFiles.Tests;
static class Program {
 static readonly List<object> results=[];static string root="";
 [DllImport("kernel32.dll",SetLastError=true)] static extern bool DeviceIoControl(SafeFileHandle h,uint code,IntPtr input,uint insize,IntPtr output,uint outsize,out uint returned,IntPtr overlapped);
 static void Assert(bool value,string message){if(!value)throw new Exception(message);}
 static async Task Check(string name,Func<Task> test){var timer=Stopwatch.StartNew();try{await test();results.Add(new{name,passed=true,ms=timer.ElapsedMilliseconds});Console.WriteLine("PASS "+name);}catch(Exception e){results.Add(new{name,passed=false,error=e.ToString()});Console.WriteLine("FAIL "+name+" "+e.Message);}}
 static Task Sync(Action x){x();return Task.CompletedTask;}
 [STAThread] static async Task<int> Main(string[] args){
  root=Path.Combine(@"D:\SmartFilesApp\TestData","run-"+DateTime.Now.ToString("yyyyMMdd-HHmmss"));Directory.CreateDirectory(root);
  if(args.Contains("--bench-core")){await PerfCore.Run(root);return 0;}
  var source=Path.Combine(root,"source");var target=Path.Combine(root,"classified");Directory.CreateDirectory(source);Directory.CreateDirectory(target);
  await Check("Invalid settings preserve live and persisted configuration",()=>Sync(()=>{var settings=new SettingsService(Path.Combine(root,"settings-atomic"));settings.Save();var original=Json.Encode(settings.Value);var candidate=Json.Decode<Settings>(original);candidate.SendText=true;candidate.CandidateCount=99;bool rejected=false;try{settings.Replace(candidate);}catch(InvalidDataException){rejected=true;}Assert(rejected&&Json.Encode(settings.Value)==original,"live settings changed after rejection");Assert(Json.Encode(new SettingsService(settings.Home).Value)==original,"persisted settings changed");foreach(double value in new[]{double.NaN,double.PositiveInfinity,double.NegativeInfinity}){candidate=Json.Decode<Settings>(original);candidate.LocalThreshold=value;rejected=false;try{SettingsService.Validate(candidate);}catch(InvalidDataException){rejected=true;}Assert(rejected,"non-finite threshold accepted");}}));
  using var db=new HistoryService(root);var tx=new FileTransactionService(db,root,target);
  string FileAt(string name,string data="hello"){var p=Path.Combine(source,name);File.WriteAllText(p,data);return p;}
  await Check("Same-volume move preserves file ID and content",async()=>{var p=FileAt("same.txt");var s=FileIdentity.Read(p);var r=await tx.MoveAsync(p,Path.Combine(target,"same.txt"),s,"test");Assert(!File.Exists(p)&&FileIdentity.Read(r.Target)==s,"not a rename");});
  await Check("Collision never overwrites",async()=>{var p=FileAt("collision.txt","new");var d=Path.Combine(target,"collision.txt");File.WriteAllText(d,"old");try{await tx.MoveAsync(p,d,FileIdentity.Read(p),"test");throw new Exception("accepted collision");}catch(IOException){}Assert(File.ReadAllText(d)=="old"&&File.Exists(p),"data lost");});
  await Check("Changed file cannot be moved from stale plan",async()=>{var p=FileAt("changed.txt");var s=FileIdentity.Read(p);File.AppendAllText(p,"new");try{await tx.MoveAsync(p,Path.Combine(target,"changed.txt"),s,"test");throw new Exception("accepted stale");}catch(IOException){}Assert(File.Exists(p),"source lost");});
  await Check("Move outside taxonomy rejected",async()=>{var p=FileAt("escape.txt");try{await tx.MoveAsync(p,Path.Combine(root,"escape.txt"),FileIdentity.Read(p),"test");throw new Exception("escape accepted");}catch(IOException){}});
  await Check("AI path traversal / unknown IDs / NaN rejected",()=>Sync(()=>{var nodes=new[]{new FolderNode("safe",target,"学习")};foreach(var json in new[]{"{\"target_folder_id\":\"../../Windows/System32\",\"confidence\":1}","{\"target_folder_id\":\"safe\",\"confidence\":1,\"parent_folder_id\":\"safe\",\"new_folder_name\":\"../evil\"}","{\"target_folder_id\":\"safe\",\"confidence\":2}"}){bool rejected=false;try{DeepSeekProvider.Validate(json,nodes,"test",true);}catch{rejected=true;}Assert(rejected,"malicious output accepted");}}));
  await Check("Reserved device names / ADS / trailing dot rejected",()=>Sync(()=>{foreach(var name in new[]{"CON","aux.txt","a:b","..","COM1.txt","x.","x ","a\\b"}){bool rejected=false;try{FileIdentity.SafeName(name);}catch{rejected=true;}Assert(rejected,name);}}));
  await Check("Undo restores identity; repeated undo rejected",async()=>{var p=FileAt("undo.txt");var s=FileIdentity.Read(p);var r=await tx.MoveAsync(p,Path.Combine(target,"undo.txt"),s,"test");await new UndoService(tx,db).UndoAsync(r);Assert(FileIdentity.Read(p)==s&&r.State=="Undone","undo failed");try{await new UndoService(tx,db).UndoAsync(r);throw new Exception("duplicate undo");}catch(IOException){}});
  await Check("Undo refuses later modifications",async()=>{var p=FileAt("undo-modified.txt");var r=await tx.MoveAsync(p,Path.Combine(target,"undo-modified.txt"),FileIdentity.Read(p),"test");File.AppendAllText(r.Target,"later");try{await new UndoService(tx,db).UndoAsync(r);throw new Exception("undo changed file");}catch(IOException){}Assert(File.Exists(r.Target),"lost modified data");});
  await Check("Cross-volume algorithm: verified copy and source removal",async()=>{var copy=new FileTransactionService(db,root,target){ForceCopyForTests=true};var p=FileAt("copy.txt",new string('a',200000));var r=await copy.MoveAsync(p,Path.Combine(target,"copy.txt"),FileIdentity.Read(p),"test");Assert(!File.Exists(p)&&new FileInfo(r.Target).Length==200000&&r.Result!.Id!=r.Original.Id,"copy transaction failed");});
  await Check("Source deletion failure rolls back published copy",async()=>{var copy=new FileTransactionService(db,root,target){ForceCopyForTests=true,FaultInjection=_=>throw new IOException("injected delete failure")};var p=FileAt("rollback.txt");var d=Path.Combine(target,"rollback.txt");try{await copy.MoveAsync(p,d,FileIdentity.Read(p),"test");throw new Exception("expected failure");}catch(IOException){}Assert(File.Exists(p)&&!File.Exists(d),"two formal copies");});
  await Check("Crash after native rename recovers without retry",()=>Sync(()=>{var p=FileAt("crash.txt");var s=FileIdentity.Read(p);var d=Path.Combine(target,"crash.txt");var r=new MoveRecord{Source=p,Target=d,Original=s,State="Moving"};db.Put("transaction",r.Id,r);File.Move(p,d);tx.Recover();Assert(db.Read<MoveRecord>("transaction").Single(x=>x.Id==r.Id).State=="Completed","not recovered");}));
  await Check("Crash after publication rolls back only owned identical copy",()=>Sync(()=>{var p=FileAt("published.txt");var d=Path.Combine(target,"published.txt");File.Copy(p,d);var r=new MoveRecord{Source=p,Target=d,Original=FileIdentity.Read(p),Result=FileIdentity.Read(d),State="Published"};db.Put("transaction",r.Id,r);tx.Recover();Assert(File.Exists(p)&&!File.Exists(d),"publication recovery failed");}));
  await Check("Owned partial copy recovery removes temp and preserves source",()=>Sync(()=>{var p=FileAt("partial-source.txt");var folder=Path.Combine(root,"TempTransfer");Directory.CreateDirectory(folder);var r=new MoveRecord{Source=p,Target=Path.Combine(target,"partial-target.txt"),Original=FileIdentity.Read(p),State="Moving"};r.Temp=Path.Combine(folder,r.Id+".part");File.WriteAllText(r.Temp,"partial");r.TempIdentity=FileIdentity.Read(r.Temp).Id;db.Put("transaction",r.Id,r);tx.Recover();Assert(File.Exists(p)&&!File.Exists(r.Temp)&&db.Find<MoveRecord>("transaction",r.Id)?.State=="Rollback","owned partial not cleaned");}));
  await Check("12 GiB sparse same-volume move: no copy and same ID",async()=>{var p=Path.Combine(source,"large.gguf");using(var f=new FileStream(p,FileMode.CreateNew,FileAccess.ReadWrite,FileShare.None)){if(!DeviceIoControl(f.SafeFileHandle,0x900C4,IntPtr.Zero,0,IntPtr.Zero,0,out _,IntPtr.Zero))throw new Exception("cannot create sparse fixture");f.SetLength(12L*1024*1024*1024);f.Write(new byte[]{1,2,3});}var s=FileIdentity.Read(p);var watch=Stopwatch.StartNew();var r=await tx.MoveAsync(p,Path.Combine(target,"large.gguf"),s,"test");Assert(FileIdentity.Read(r.Target)==s&&watch.ElapsedMilliseconds<1500,"large file copy suspected");});
  await Check("200 native renames preserve exact Unicode paths",async()=>{for(int i=0;i<200;i++){var p=FileAt("rename-"+i+"-极限.txt");var d=Path.Combine(target,"renamed-"+i+"-极限.txt");var r=await tx.MoveAsync(p,d,FileIdentity.Read(p),"test");Assert(File.Exists(d)&&r.State=="Completed","rename path mismatch");}});
  await Check("Strict cross-volume hash and undo",async()=>{var copy=new FileTransactionService(db,root,target){ForceCopyForTests=true,StrictHash=true};var p=FileAt("strict.txt",new string('Z',180000));var r=await copy.MoveAsync(p,Path.Combine(target,"strict.txt"),FileIdentity.Read(p),"test");await new UndoService(copy,db).UndoAsync(r);Assert(File.Exists(p)&&File.ReadAllText(p).Length==180000,"strict undo failed");});
  var watchSource=Path.Combine(root,"watcher");Directory.CreateDirectory(watchSource);
  for(int i=0;i<5000;i++)File.WriteAllText(Path.Combine(watchSource,$"old-{i}.txt"),"old");
  var received=new ConcurrentBag<(string,Stamp,DateTime)>();var faults=new ConcurrentBag<string>();
  using(var watcher=new SourceWatcher(new(){Name="test",Path=watchSource,Enabled=true},(p,s,id,t)=>received.Add((p,id,t)),_=>{},faults.Add)){
   await Check("5000 old files and 1000 timestamp changes stay excluded",async()=>{for(int i=0;i<1000;i++)File.SetLastWriteTimeUtc(Path.Combine(watchSource,$"old-{i}.txt"),DateTime.UtcNow);File.Move(Path.Combine(watchSource,"old-0.txt"),Path.Combine(watchSource,"renamed-old.txt"));await Task.Delay(800);Assert(received.IsEmpty,"old files admitted");});
   await Check("Browser .crdownload rename admitted exactly once",async()=>{var p=Path.Combine(watchSource,"download.zip.crdownload");File.WriteAllText(p,"zip");await Task.Delay(250);Assert(received.IsEmpty,"temp admitted");File.Move(p,Path.Combine(watchSource,"download.zip"));await Task.Delay(1200);Assert(received.Count==1&&received.First().Item1.EndsWith("download.zip"),"missing / duplicate completion");});
   await Check("Old temporary download renamed after arming stays excluded",async()=>{var old=Path.Combine(watchSource,"old-1.txt");File.Move(old,Path.Combine(watchSource,"old-temp.crdownload"));await Task.Delay(100);File.Move(Path.Combine(watchSource,"old-temp.crdownload"),Path.Combine(watchSource,"old-temp.pdf"));await Task.Delay(600);Assert(received.Count==1,"old temp promoted");});
   await Check("Deleted fresh file does not produce a result",async()=>{var p=Path.Combine(watchSource,"vanish.txt");File.WriteAllText(p,"x");File.Delete(p);await Task.Delay(600);Assert(received.Count==1,"deleted file admitted");});
   await Check("100 new image files deduplicate and batch intake",async()=>{for(int i=0;i<100;i++)File.WriteAllText(Path.Combine(watchSource,$"IMG_{i}.png"),"synthetic fixture");await Task.Delay(3000);Assert(received.Count==101&&received.Select(x=>x.Item2.Id).Distinct().Count()==101,"lost or duplicate files");Assert(faults.IsEmpty,"watcher overflow");});
  }
   await Check("Exclusive writer at Created is retried until completion",async()=>{using var lockedWatcher=new SourceWatcher(new(){Name="lock",Path=watchSource,Enabled=true},(p,s,id,t)=>received.Add((p,id,t)),_=>{},faults.Add);var before=received.Count;var p=Path.Combine(watchSource,"locked-download.bin");using(var stream=new FileStream(p,FileMode.CreateNew,FileAccess.Write,FileShare.None)){stream.Write(new byte[100]);await Task.Delay(800);Assert(received.Count==before,"locked writer admitted");}await Task.Delay(1800);Assert(received.Count==before+1,"exclusive Created was lost");});
  await Check("Local installer recommendation under 300 ms",()=>Sync(()=>{using var taxonomy=new TaxonomyService(Path.Combine(root,"tree"),db);var classifier=new LocalClassifier(new RuleEngine(db));var sw=Stopwatch.StartNew();var r=classifier.Classify(new("VSCodeUserSetup-x64.exe",".exe",100,"","",false),"Downloads",taxonomy.Nodes);Assert(r.Confidence>=.95&&sw.ElapsedMilliseconds<300,"local classification slow/wrong");}));
  await Check("One correction does not become an absolute rule",()=>Sync(()=>{var rule=new RuleEngine(db);rule.Learn("极限 Stolz", "test-folder");Assert(rule.Match("Stolz",new[]{new FolderNode("test-folder","x","学习")})==null,"one sample absolute rule");}));
  await Check("Source discovery is read-only and returns configured paths",()=>Sync(()=>{var sources=new SourceDiscovery().Discover(@"D:\SmartFiles");File.WriteAllText(Path.Combine(root,"discovered-sources.json"),Json.Encode(sources));Assert(sources.Any(x=>x.Name.Contains("_Inbox")),"inbox missing");}));
  await Check("API privacy / concurrency / injection / bounded retry",()=>ApiTests.Run(Path.Combine(root,"api")));
  await Check("End-to-end deleted file / late TTL / explicit approval",()=>ApiTests.Lifecycle(Path.Combine(root,"lifecycle")));
  await Check("100000-record retention / storage caps / model and ZIP privacy",()=>StoragePrivacyTests.Run(Path.Combine(root,"storage-privacy")));
  Directory.CreateDirectory(@"D:\SmartFilesApp\DevArtifacts");File.WriteAllText(@"D:\SmartFilesApp\DevArtifacts\test-results.json",Json.Encode(results));
  File.WriteAllText(@"D:\SmartFilesApp\DevArtifacts\latest-test-root.txt",root);
  return results.Any(x=>Json.Encode(x).Contains("\"passed\": false"))?1:0;
 }
}
